select id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, lag(temp_c, 1, 0) over (partition by device_code order by pressure, id) as prev_temp_c, sum(status_bits) over (partition by device_code order by cast(reading_ts as bigint) range between 7200 preceding and current row) as status_bits_sum_2h, sum(pressure) over (partition by device_code order by humidity, id rows between unbounded preceding and current row) as running_pressure, avg(pressure) over (partition by device_code order by cast(reading_ts as bigint) range between 7200 preceding and current row) as pressure_avg_2h from device_readings;
